svg.appendChild(txt("APR 16 PEAK", {x:peakX,y:peakY-10,"text-anchor":"middle","font-size":7,"font-weight":700,fill:"#1a3560","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
