var lastX = xp(n-1), lastY = yp(data[n-1].v);
svg.appendChild(el("circle",{cx:lastX,cy:lastY,r:4,fill:"#e8a825"}));
var pillW = 74, pillH = 16;
var pillX = lastX - pillW - 6;
var pillY = lastY - pillH/2;
if(pillX < margin.left){pillX = lastX + 6;}
svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,fill:"#e8a825",rx:2}));
svg.appendChild(txt("$4,167.50", {x:pillX+pillW/2,y:pillY+pillH/2+4,"text-anchor":"middle","font-size":9,"font-weight":700,fill:"#111"}));
svg.appendChild(txt("TANKERS STRUCK JUL 6 EVE", {x:lastX-4,y:margin.top+PH-24,"text-anchor":"end","font-size":7,"font-weight":700,fill:"#8a3030","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
if(_cs && _cs.parentNode){ _cs.parentNode.appendChild(svg); }
