function txt(content, attrs){var t=el("text", attrs);t.textContent=content;return t;}
var data = [{"m":"Aug 25","v":1.9},{"m":"Sep 25","v":2.4},{"m":"Oct 25","v":2.2},{"m":"Nov 25","v":2.2},{"m":"Dec 25","v":2.4},{"m":"Jan 26","v":2.3},{"m":"Feb 26","v":1.8},{"m":"Mar 26","v":2.4},{"m":"Apr 26","v":2.8},{"m":"May 26","v":3.2}];
var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
