}
svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:margin.top+PH,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":1}));
var refY = yp(2);
svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:refY,y2:refY,stroke:"#2e7d32","stroke-dasharray":"3,3"}));
svg.appendChild(txt("BOC 2% TARGET", {x:margin.left+10,y:refY-4,"text-anchor":"start","font-size":7,"font-weight":700,fill:"#2e7d32","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
var pathD = "";
for(var i=0;i<n;i++){
  var x = xp(i), y = yp(data[i].v);
  pathD += (i===0 ? "M" : "L") + x + "," + y + " ";
}
svg.appendChild(el("path",{d:pathD, fill:"none", stroke:"#4a5568", "stroke-width":2}));
for(var i=0;i<n;i++){
  svg.appendChild(txt(data[i].m, {x:xp(i),y:margin.top+PH+16,"text-anchor":"middle","font-size":7,fill:"#999","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
}
var lastX = xp(n-1), lastY = yp(data[n-1].v);
svg.appendChild(el("circle",{cx:lastX,cy:lastY,r:4,fill:"#e8a825"}));
var pillW = 46, pillH = 16;
var pillX = lastX - pillW - 6;
var pillY = lastY - pillH/2;
if(pillX < margin.left){pillX = lastX + 6;}
svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,fill:"#e8a825",rx:2}));
svg.appendChild(txt("3.2%", {x:pillX+pillW/2,y:pillY+pillH/2+4,"text-anchor":"middle","font-size":9,"font-weight":700,fill:"#111"}));
svg.appendChild(txt("JUNE CPI ARRIVES JUL 20", {x:lastX-4,y:margin.top+16,"text-anchor":"end","font-size":7,"font-weight":700,fill:"#1a3560","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
if(_cs && _cs.parentNode){ _cs.parentNode.appendChild(svg); }
