  svg.appendChild(txt(data[i].d, {x:xp(i),y:margin.top+PH+16,"text-anchor":"middle","font-size":7,fill:"#999","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
}
var lastX = xp(n-1), lastY = yp(data[n-1].v);
svg.appendChild(el("circle",{cx:lastX,cy:lastY,r:4,fill:"#e8a825"}));
