svg.appendChild(txt("$68.55", {x:pillX+pillW/2,y:pillY+pillH/2+4,"text-anchor":"middle","font-size":9,"font-weight":700,fill:"#111"}));
svg.appendChild(txt("ATTACK JUL 6 EVE, PRICE FLAT", {x:lastX-4,y:margin.top+PH-40,"text-anchor":"end","font-size":7,"font-weight":700,fill:"#8a3030","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
